using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "BaseStarRequirementBattleActionData", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/BaseStarRequirementBattleActionData")]
public class BaseStarRequirementBattleActionData : BaseBattleActionData
{
	[Header("Star Ability")]
	[SerializeField]
	private StarAbility starAbility;

	[SerializeField]
	private bool muteStarRequirement;

	public override string GetActionDescription(int amount, int bonusAmount, BattleAction battleAction, bool addTimelessTag, Dice dice = null, DiceFace diceFace = null, bool noRefreshedActionDescription = true, bool forgeDiceFace = false)
	{
		string text = "";
		text = ((!base.EnableCustomDescription) ? Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(base.ActionIDDescription), GetAmountModifiedString(amount, 0)) : customBattleActionDescription.GetActionDescription(GetAmountModifiedString(amount, 0), battleAction));
		if (muteStarRequirement)
		{
			return text;
		}
		return starAbility.GetLocalizedRequirement() + "\n" + text;
	}
}
